func (this *Aster) ParseMarginModification(data any, optionalArgs ...any) map[string]any {
	//
	//     {
	//         "amount": "100",
	//         "asset": "USDT",
	//         "symbol": "BTCUSDT",
	//         "time": 1578047900425,
	//         "type": 1,
	//         "positionSide": "LONG"
	//     }
	//
	//     {
	//         "amount": 100.0,
	//         "code": 200,
	//         "msg": "Successfully modify position margin.",
	//         "type": 1
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var rawType *int64 = this.SafeInteger(data, "type")
	var errorCode *string = this.SafeString(data, "code")
	var marketId *string = this.SafeString(data, "symbol")
	var timestamp *int64 = this.SafeInteger(data, "time")
	var marketResolved map[string]any = this.SafeMarket(marketId, market, nil, "swap")
	var noErrorCode bool = (errorCode == nil)
	var success bool = (errorCode != nil && *errorCode == "200")
	return map[string]any{
		"info":   data,
		"symbol": marketResolved["symbol"],
		"type": func() string {
			if rawType != nil && *rawType == 1 {
				return "add"
			}
			return "reduce"
		}(),
		"marginMode": "isolated",
		"amount":     this.SafeNumber(data, "amount"),
		"code":       this.SafeString(data, "asset"),
		"total":      nil,
		"status": func() string {
			if success || noErrorCode {
				return "ok"
			}
			return "failed"
		}(),
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
	}
}
