func (this *Aster) ParseLedgerEntry(item any, optionalArgs ...any) LedgerEntry {
	//
	//     {
	//         "symbol": "",
	//         "incomeType": "TRANSFER",
	//         "income": "10.00000000",
	//         "asset": "USDT",
	//         "time": 1677645250000,
	//         "info": "TRANSFER",
	//         "tranId": 131001573082,
	//         "tradeId": ""
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var amount *string = this.SafeString(item, "income")
	var direction string
	if Precise.StringLe(amount, "0") {
		direction = "out"
		amount = Precise.StringMul("-1", amount)
	} else {
		direction = "in"
	}
	var currencyId *string = this.SafeString(item, "asset")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var currencyResolved map[string]any = this.SafeCurrency(currencyId, currency)
	var timestamp *int64 = this.SafeInteger(item, "time")
	var typeVar *string = this.SafeString(item, "incomeType")
	return this.SafeLedgerEntry(map[string]any{
		"info":             item,
		"id":               this.SafeString(item, "tranId"),
		"direction":        direction,
		"account":          nil,
		"referenceAccount": nil,
		"referenceId":      this.SafeString(item, "tradeId"),
		"type":             this.ParseLedgerEntryType(typeVar),
		"currency":         code,
		"amount":           this.ParseNumber(amount),
		"timestamp":        timestamp,
		"datetime":         this.Iso8601(timestamp),
		"before":           nil,
		"after":            nil,
		"status":           nil,
		"fee":              nil,
	}, currencyResolved)
}
func (this *Aster) ParseLedgerEntryType(typeVar *string) *string {
	var ledgerType map[string]any = map[string]any{
		"TRANSFER":                      "transfer",
		"WELCOME_BONUS":                 "cashback",
		"REALIZED_PNL":                  "trade",
		"FUNDING_FEE":                   "fee",
		"COMMISSION":                    "commission",
		"INSURANCE_CLEAR":               "settlement",
		"MARKET_MERCHANT_RETURN_REWARD": "cashback",
	}
	return this.SafeString(ledgerType, typeVar, typeVar)
}

